create or replace function public.schedule_relation_selector_matches_v1(p_selector jsonb,p_activity_key text,p_assignment_id uuid,p_course_id uuid,p_teacher_id uuid,p_class_id uuid) returns boolean language sql immutable set search_path=public as $$ select (coalesce(nullif(p_selector->>'activity_key',''),'')='' or p_activity_key=p_selector->>'activity_key') and (coalesce(nullif(p_selector->>'assignment_id',''),'')='' or p_assignment_id::text=p_selector->>'assignment_id') and (coalesce(nullif(p_selector->>'course_id',''),'')='' or p_course_id::text=p_selector->>'course_id') and (coalesce(nullif(p_selector->>'teacher_id',''),'')='' or p_teacher_id::text=p_selector->>'teacher_id') and (coalesce(nullif(p_selector->>'class_id',''),'')='' or p_class_id::text=p_selector->>'class_id') $$;
create or replace function public.schedule_relation_unary_violates_v1(p_type text,p_params jsonb,p_day smallint,p_start smallint,p_end smallint) returns boolean language plpgsql immutable set search_path=public as $$ declare t text:=upper(coalesce(p_type,''));v int;days int[];periods int[];inside boolean;begin if t='STARTS_DAY' then v:=coalesce(nullif(p_params->>'first_period','')::int,1);return p_start<>v;elsif t='ENDS_DAY' then if nullif(p_params->>'last_period','') is null then return false;end if;v:=(p_params->>'last_period')::int;return p_end<>v;elsif t in('PREFERRED_SLOT','FORBIDDEN_SLOT') then select coalesce(array_agg(x::int),'{}') into days from jsonb_array_elements_text(coalesce(p_params->'days','[]'::jsonb))x;select coalesce(array_agg(x::int),'{}') into periods from jsonb_array_elements_text(coalesce(p_params->'periods','[]'::jsonb))x;if cardinality(days)=0 and cardinality(periods)=0 then return false;end if;inside:=(cardinality(days)=0 or p_day=any(days)) and (cardinality(periods)=0 or exists(select 1 from unnest(periods)q where q between p_start and p_end));return case when t='PREFERRED_SLOT' then not inside else inside end;end if;return false;end $$;
create or replace function public.schedule_relation_pair_violates_v1(p_type text,p_params jsonb,l_day smallint,l_start smallint,l_end smallint,l_room uuid,r_day smallint,r_start smallint,r_end smallint,r_room uuid) returns boolean language plpgsql immutable set search_path=public as $$ declare t text:=upper(coalesce(p_type,''));n int:=coalesce(nullif(coalesce(p_params->>'periods',p_params->>'gap',p_params->>'days',p_params->>'value'),'')::int,0);g int;ov boolean;begin ov:=l_day=r_day and l_start<=r_end and r_start<=l_end;if t='SAME_TIME' then return l_day<>r_day or l_start<>r_start;elsif t='DIFFERENT_TIME' then return l_day=r_day and l_start=r_start;elsif t='SAME_START' then return l_start<>r_start;elsif t='SAME_DAY' then return l_day<>r_day;elsif t='DIFFERENT_DAY' then return l_day=r_day;elsif t='SAME_ROOM' then return l_room is not null and r_room is not null and l_room<>r_room;elsif t='DIFFERENT_ROOM' then return l_room is not null and r_room is not null and l_room=r_room;elsif t='ORDERED' then return not(l_day<r_day or(l_day=r_day and l_end<r_start));elsif t='CONSECUTIVE' then return l_day<>r_day or r_start<>l_end+1;elsif t='OVERLAP' then return not ov;elsif t='NOT_OVERLAP' then return ov;elsif t='MIN_DAYS' then return abs(l_day-r_day)<n;elsif t='MAX_DAYS' then return abs(l_day-r_day)>n;elsif t in('MIN_GAP','MAX_GAP') then if l_day<>r_day then return t='MAX_GAP';end if;if l_end<r_start then g:=r_start-l_end-1;elsif r_end<l_start then g:=l_start-r_end-1;else g:=-1;end if;return case when t='MIN_GAP' then g<n else g>n end;end if;return false;end $$;
create or replace function public.validate_schedule_planning_relation_definition_v1() returns trigger language plpgsql set search_path=public as $$ declare t text:=upper(btrim(new.relation_type));begin if t<>all(array['SAME_TIME','DIFFERENT_TIME','SAME_START','SAME_DAY','DIFFERENT_DAY','SAME_ROOM','DIFFERENT_ROOM','ORDERED','CONSECUTIVE','OVERLAP','NOT_OVERLAP','MIN_GAP','MAX_GAP','MIN_DAYS','MAX_DAYS','STARTS_DAY','ENDS_DAY','PREFERRED_SLOT','FORBIDDEN_SLOT']) then raise exception 'UNSUPPORTED_PLANNING_RELATION_TYPE: %',t;end if;new.relation_type:=t;new.left_selector:=coalesce(new.left_selector,'{}'::jsonb);new.right_selector:=coalesce(new.right_selector,'{}'::jsonb);new.parameters:=coalesce(new.parameters,'{}'::jsonb);if t in('STARTS_DAY','ENDS_DAY','PREFERRED_SLOT','FORBIDDEN_SLOT') then new.right_selector:='{}'::jsonb;end if;return new;end $$;
drop trigger if exists trg_validate_schedule_planning_relation_definition_v1 on public.schedule_planning_relations;create trigger trg_validate_schedule_planning_relation_definition_v1 before insert or update on public.schedule_planning_relations for each row execute function public.validate_schedule_planning_relation_definition_v1();
create or replace function public.get_schedule_generic_relation_evaluation_v1(p_scenario_id uuid default null) returns table(relation_id uuid,relation_type text,mode text,violation_count integer,penalty numeric) language plpgsql stable security definer set search_path=public as $$ begin if p_scenario_id is not null then perform public.assert_schedule_scenario_tenant_phase3_v1(p_scenario_id);end if;return query with raw as(select ts.id,ts.block_key,ts.teacher_assignment_id assignment_id,ts.course_id,ts.teacher_id,ts.class_id,ts.weekday,ts.period,ts.classroom_id from public.teacher_schedule ts where p_scenario_id is null and ts.active and ts.institution_code=public.current_tenant_code() union all select sr.id,sr.block_key,sr.teacher_assignment_id,sr.course_id,sr.teacher_id,sr.class_id,sr.weekday,sr.period,sr.classroom_id from public.schedule_scenario_rows sr where p_scenario_id is not null and sr.scenario_id=p_scenario_id and sr.institution_code=public.current_tenant_code()),a as(select coalesce(block_key::text,id::text) activity_key,assignment_id,course_id,teacher_id,class_id,weekday,min(period)::smallint start_p,max(period)::smallint end_p,case when count(distinct classroom_id)<=1 then (array_agg(classroom_id) filter(where classroom_id is not null))[1] else null end classroom_id from raw group by coalesce(block_key::text,id::text),assignment_id,course_id,teacher_id,class_id,weekday),r as(select * from public.schedule_planning_relations x where x.active and x.mode<>'OFF' and public.tenant_row_allowed(x.institution_code) and(x.effective_from is null or x.effective_from<=current_date)and(x.effective_to is null or x.effective_to>=current_date)),u as(select r.id,r.relation_type,r.mode,r.weight,count(*)::int n from r join a l on public.schedule_relation_selector_matches_v1(r.left_selector,l.activity_key,l.assignment_id,l.course_id,l.teacher_id,l.class_id) where upper(r.relation_type) in('STARTS_DAY','ENDS_DAY','PREFERRED_SLOT','FORBIDDEN_SLOT') and public.schedule_relation_unary_violates_v1(r.relation_type,r.parameters,l.weekday,l.start_p,l.end_p) group by r.id,r.relation_type,r.mode,r.weight),b as(select r.id,r.relation_type,r.mode,r.weight,count(*)::int n from r join a l on public.schedule_relation_selector_matches_v1(r.left_selector,l.activity_key,l.assignment_id,l.course_id,l.teacher_id,l.class_id) join a rr on rr.activity_key<>l.activity_key and public.schedule_relation_selector_matches_v1(r.right_selector,rr.activity_key,rr.assignment_id,rr.course_id,rr.teacher_id,rr.class_id) where upper(r.relation_type) not in('STARTS_DAY','ENDS_DAY','PREFERRED_SLOT','FORBIDDEN_SLOT') and(case when upper(r.relation_type) in('SAME_TIME','DIFFERENT_TIME','SAME_START','SAME_DAY','DIFFERENT_DAY','SAME_ROOM','DIFFERENT_ROOM','OVERLAP','NOT_OVERLAP','MIN_GAP','MAX_GAP','MIN_DAYS','MAX_DAYS') and r.left_selector=r.right_selector then l.activity_key<rr.activity_key else true end) and public.schedule_relation_pair_violates_v1(r.relation_type,r.parameters,l.weekday,l.start_p,l.end_p,l.classroom_id,rr.weekday,rr.start_p,rr.end_p,rr.classroom_id) group by r.id,r.relation_type,r.mode,r.weight),v as(select * from u union all select * from b) select v.id,v.relation_type,v.mode,sum(v.n)::int,sum(v.n*v.weight) from v group by v.id,v.relation_type,v.mode;end $$;
create or replace function public.get_schedule_scenario_generic_relation_summary_v1(p_scenario_id uuid) returns table(hard numeric,medium numeric,soft numeric,hard_violations integer) language sql stable security definer set search_path=public as $$ select coalesce(sum(penalty)filter(where mode='HARD'),0),coalesce(sum(penalty)filter(where mode='MEDIUM'),0),coalesce(sum(penalty)filter(where mode='SOFT'),0),coalesce(sum(violation_count)filter(where mode='HARD'),0)::int from public.get_schedule_generic_relation_evaluation_v1(p_scenario_id) $$;
create or replace function public.get_schedule_current_generic_relation_summary_v1() returns table(hard numeric,medium numeric,soft numeric,hard_violations integer) language sql stable security definer set search_path=public as $$ select coalesce(sum(penalty)filter(where mode='HARD'),0),coalesce(sum(penalty)filter(where mode='MEDIUM'),0),coalesce(sum(penalty)filter(where mode='SOFT'),0),coalesce(sum(violation_count)filter(where mode='HARD'),0)::int from public.get_schedule_generic_relation_evaluation_v1(null) $$;
create or replace function public.get_schedule_scenario_generic_relation_issues_v1(p_scenario_id uuid) returns table(code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$ select 'GENERIC_RELATION_'||relation_type,violation_count,'Generic HARD planlama ilişkisi ihlal edildi: '||relation_type from public.get_schedule_generic_relation_evaluation_v1(p_scenario_id) where mode='HARD' and violation_count>0 $$;
create or replace function public.assert_schedule_current_generic_relations_v1() returns void language plpgsql stable security definer set search_path=public as $$ declare n int;begin select hard_violations into n from public.get_schedule_current_generic_relation_summary_v1();if coalesce(n,0)>0 then raise exception 'GENERIC_HARD_RELATION_VIOLATION: %',n;end if;end $$;
create or replace function public.trg_assert_schedule_generic_relations_v1() returns trigger language plpgsql security definer set search_path=public as $$ begin if current_setting('okulos.generic_relations_checked',true)='1' then return null;end if;perform public.assert_schedule_current_generic_relations_v1();perform set_config('okulos.generic_relations_checked','1',true);return null;end $$;
drop trigger if exists trg_assert_schedule_generic_relations_v1 on public.teacher_schedule;create constraint trigger trg_assert_schedule_generic_relations_v1 after insert or update or delete on public.teacher_schedule deferrable initially deferred for each row execute function public.trg_assert_schedule_generic_relations_v1();
create or replace function public.get_schedule_scenario_hard_issues_v2(p_scenario_id uuid) returns table(code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$ select * from public.get_schedule_scenario_hard_issues_pre_phase3(p_scenario_id) union all select * from public.get_schedule_phase3_scenario_issues_v1(p_scenario_id) union all select * from public.get_schedule_scenario_custom_rule_issues_v1(p_scenario_id) union all select * from public.get_schedule_scenario_generic_relation_issues_v1(p_scenario_id) $$;
create or replace function public.validate_schedule_scenario_v2(p_scenario_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare n int;begin perform public.assert_schedule_scenario_tenant_phase3_v1(p_scenario_id);n:=public.validate_schedule_scenario_pre_phase3_tenant(p_scenario_id);select n+coalesce(sum(affected_count),0)::int into n from public.get_schedule_scenario_generic_relation_issues_v1(p_scenario_id);return n;end $$;
create or replace function public.get_schedule_scenario_objective_vector_v1(p_scenario_id uuid) returns table(hard integer,unplaced integer,medium numeric,soft numeric,legacy_score integer) language sql stable security definer set search_path=public as $$ with g as(select * from public.get_schedule_scenario_generic_relation_summary_v1(p_scenario_id)),s as(select * from public.get_schedule_scenario_student_conflict_summary_v1(p_scenario_id)),h as(select coalesce(sum(affected_count),0)::int n from public.get_schedule_scenario_hard_issues_v2(p_scenario_id)),u as(select count(*)::int n from public.schedule_unplaced_items where scenario_id=p_scenario_id) select h.n,u.n,coalesce(g.medium,0)+coalesce(s.weighted_conflict,0),coalesce(g.soft,0),public.calculate_schedule_scenario_score_v2(p_scenario_id) from g,s,h,u $$;
create or replace function public.preview_schedule_batch_move_v1(p_moves jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare e jsonb;r teacher_schedule%rowtype;n int;ok boolean:=false;msg text;begin perform open_permission_context('schedule.edit');if jsonb_typeof(p_moves)<>'array' or jsonb_array_length(p_moves)=0 or jsonb_array_length(p_moves)>100 then return jsonb_build_object('ok',false,'error','BATCH_SIZE_INVALID');end if;select count(distinct (x->>'schedule_id')::uuid) into n from jsonb_array_elements(p_moves)x;if n<>jsonb_array_length(p_moves) then return jsonb_build_object('ok',false,'error','DUPLICATE_SCHEDULE_ROW');end if;select count(*) into n from teacher_schedule where active and institution_code=current_tenant_code() and not locked and id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);if n<>jsonb_array_length(p_moves) then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND_OR_LOCKED');end if;begin update teacher_schedule set active=false where id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);for e in select * from jsonb_array_elements(p_moves) loop select * into r from teacher_schedule where id=(e->>'schedule_id')::uuid and institution_code=current_tenant_code();perform upsert_schedule_slot_permission_core_v2(r.teacher_assignment_id,(e->>'weekday')::smallint,(e->>'period')::smallint,coalesce(nullif(e->>'classroom_id','')::uuid,r.classroom_id),r.subgroup_id,r.id,false,'manual');end loop;perform public.assert_schedule_current_generic_relations_v1();ok:=true;raise exception using errcode='P0001',message='OKULOS_PREVIEW_ROLLBACK';exception when others then if SQLERRM='OKULOS_PREVIEW_ROLLBACK' and ok then return jsonb_build_object('ok',true,'count',jsonb_array_length(p_moves));else msg:=SQLERRM;return jsonb_build_object('ok',false,'error',msg);end if;end;end $$;
create or replace function public.move_schedule_slots_batch_v1(p_moves jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare e jsonb;r teacher_schedule%rowtype;n int;begin perform open_permission_context('schedule.edit');if jsonb_typeof(p_moves)<>'array' or jsonb_array_length(p_moves)=0 or jsonb_array_length(p_moves)>100 then raise exception 'BATCH_SIZE_INVALID';end if;select count(distinct (x->>'schedule_id')::uuid) into n from jsonb_array_elements(p_moves)x;if n<>jsonb_array_length(p_moves) then raise exception 'DUPLICATE_SCHEDULE_ROW';end if;perform 1 from teacher_schedule where active and institution_code=current_tenant_code() and not locked and id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x) for update;select count(*) into n from teacher_schedule where active and institution_code=current_tenant_code() and not locked and id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);if n<>jsonb_array_length(p_moves) then raise exception 'SCHEDULE_ROW_NOT_FOUND_OR_LOCKED';end if;perform create_schedule_restore_point('Toplu taşıma öncesi','Ders programı güvenli çoklu taşıma geri dönüş noktası');update teacher_schedule set active=false where id in(select (x->>'schedule_id')::uuid from jsonb_array_elements(p_moves)x);for e in select * from jsonb_array_elements(p_moves) loop select * into r from teacher_schedule where id=(e->>'schedule_id')::uuid and institution_code=current_tenant_code();perform upsert_schedule_slot_permission_core_v2(r.teacher_assignment_id,(e->>'weekday')::smallint,(e->>'period')::smallint,coalesce(nullif(e->>'classroom_id','')::uuid,r.classroom_id),r.subgroup_id,r.id,false,'manual');end loop;perform public.assert_schedule_current_generic_relations_v1();return jsonb_build_object('ok',true,'count',n);end $$;
revoke all on function public.get_schedule_generic_relation_evaluation_v1(uuid) from public;grant execute on function public.get_schedule_generic_relation_evaluation_v1(uuid) to authenticated;revoke all on function public.get_schedule_scenario_generic_relation_summary_v1(uuid) from public;grant execute on function public.get_schedule_scenario_generic_relation_summary_v1(uuid) to authenticated;revoke all on function public.get_schedule_current_generic_relation_summary_v1() from public;grant execute on function public.get_schedule_current_generic_relation_summary_v1() to authenticated;revoke all on function public.get_schedule_scenario_objective_vector_v1(uuid) from public;grant execute on function public.get_schedule_scenario_objective_vector_v1(uuid) to authenticated;
